#define COMPAT_ENTRY_COUNT 559

size_t pops_compat_db_count(void) {
  return COMPAT_ENTRY_COUNT;
}

const PopsCompatEntry *pops_compat_db_get(size_t index) {
  if (index >= COMPAT_ENTRY_COUNT)
    return NULL;
  return &s_compat_entries[index];
}

static void normalize_for_lookup(const char *in, char *out, size_t out_size) {
  size_t pos = 0;
  while (*in && pos < out_size - 1) {
    if (isalnum((unsigned char)*in)) {
      out[pos++] = (char)toupper((unsigned char)*in);
    }
    in++;
  }
  out[pos] = '\0';
}

const PopsCompatEntry *pops_compat_db_lookup(const char *serial) {
  if (!serial || !serial[0])
    return NULL;

  char key[32];
  normalize_for_lookup(serial, key, sizeof(key));
  if (!key[0])
    return NULL;

  /* Linear scan with normalized comparison */
  for (size_t i = 0; i < COMPAT_ENTRY_COUNT; ++i) {
    char entry_key[32];
    normalize_for_lookup(s_compat_entries[i].serial, entry_key, sizeof(entry_key));
    if (!strcmp(key, entry_key))
      return &s_compat_entries[i];
  }

  return NULL;
}
